```c
#include <stdio.h>
#include <stdlib.h>

int cmp_double(const void *a, const void *b) {
    double da = *(const double *)a;
    double db = *(const double *)b;
    if (da < db) return -1;
    if (da > db) return 1;
    return 0;
}

int main(void) {
    double t;
    int n;

    if (scanf("%lf", &t) != 1) return 0;
    if (scanf("%d", &n) != 1) return 0;

    double *x = (double *)malloc(n * sizeof(double));
    if (!x) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lf", &x[i]);
    }

    qsort(x, n, sizeof(double), cmp_double);

    double min_viz = (x[0] + x[1]) / 2.0;

    for (int i = 1; i < n - 1; i++) {
        double viz = (x[i + 1] - x[i - 1]) / 2.0;
        if (viz < min_viz) {
            min_viz = viz;
        }
    }

    double last_viz = t - (x[n - 2] + x[n - 1]) / 2.0;
    if (last_viz < min_viz) {
        min_viz = last_viz;
    }

    printf("%.2f\n", min_viz);

    free(x);
    return 0;
}
```

